	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: ok.ID})
	if len(invs) != 2 || invs[1].Status != store.InvoicePaid {
		t.Fatalf("the subscription after the failed one = %+v, want its renewal paid", invs)
	}
}

func TestDeclinedRenewalIsPastDue(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := renewableSub(t, e, "jane@example.com", "pm_card_declined")
	if n, err := e.Subs.RenewDue(ctx); n != 1 || err != nil {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.PastDue {
		t.Fatalf("status = %s, want past due", got.Status)
	}
	if n, err := e.Subs.RenewDue(ctx); n != 0 || err != nil {
		t.Fatalf("a declined renewal was retried by the next run: %d, %v", n, err)
	}
}
