}

func TestOverlappingRenewalsInvoiceOnce(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := renewableSub(t, e, "jane@example.com", "pm_card_visa")
	const runs = 8
	var wg sync.WaitGroup
	start := make(chan struct{})
	renewed := make([]int, runs)
	for i := 0; i < runs; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			n, err := e.Subs.RenewDue(ctx)
			if err != nil {
				t.Error(err)
			}
			renewed[i] = n
		}()
	}
