// lock, so a subscription is renewed once per period even when calls overlap, and a failed charge is not billed again by a
// later call. It reports whether this call renewed or canceled the subscription. A subscription that another call already
// moved on is left alone without an error.
func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) (bool, error) {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return false, store.ErrNotFound
	}
	dueEnd := sub.CurrentPeriodEnd
	if sub.CancelAtPeriodEnd {
		canceled, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			if x.Status == store.Canceled || !x.CurrentPeriodEnd.Equal(dueEnd) {
				return store.ErrNotDue
			}
			x.Status, x.CanceledAt = store.Canceled, &dueEnd
			return nil
		})
		if errors.Is(err, store.ErrNotDue) {
			return false, nil
		}
		if err != nil {
			return false, err
		}
		s.publish(ctx, canceled.OrgID, "subscription.canceled", canceled)
		return true, nil
	}
	start := now
	end := billing.AddInterval(start, plan.Interval)
	var invoice *store.Invoice
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		inv := s.periodInvoice(sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		invoice = &inv
	case plan.UsageType == store.Licensed:
		inv := s.periodInvoice(sub, plan, start, end)
		invoice = &inv
	}
	next, inv, err := s.Store.RenewSubscription(sub.OrgID, sub.ID, dueEnd, start, end, invoice, now)
	if errors.Is(err, store.ErrNotDue) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	paid := true
	if inv != nil {
		if paid, err = s.collect(ctx, *inv); err != nil {
			// The gateway failed: nothing was taken, the invoice stays open and the status is kept.
			s.publish(ctx, next.OrgID, "subscription.updated", next)
			return true, err
		}
	}
	status := store.Active
	if !paid {
		status = store.PastDue
	}
	if _, err := s.setStatus(ctx, next, status); err != nil {
		return true, err
	}
	return true, nil
}

// periodInvoice builds, without storing it, the invoice of one period of a subscription.
func (s *Service) periodInvoice(sub store.Subscription, plan store.Plan, start, end time.Time) store.Invoice {
	var lines []store.Line
	period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
	switch plan.UsageType {
	case store.Licensed:
		if plan.UnitAmount > 0 {
			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
		}
	case store.Metered:
		if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
			lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
		}
	}
	ps, pe := start, end
	return store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}
}

// collect charges a stored invoice to the customer's default payment method. It reports false when the charge was declined.
// An invoice that needs no charge is marked paid; one whose customer has no payment method stays open and counts as paid
// here (it is paid by hand). An unavailable gateway returns an error wrapping payments.ErrUnavailable.
func (s *Service) collect(ctx context.Context, inv store.Invoice) (bool, error) {
	s.publish(ctx, inv.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": inv.SubscriptionID})
	_, _, err := s.Payments.Pay(ctx, inv.OrgID, inv.ID, "")
	var decline *payments.DeclineError
	switch {
	case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
		return true, nil
	case errors.As(err, &decline):
		return false, nil
	default:
		return false, err
	}
}

func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
	sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.Status = st
		return nil
	})
	if err == nil {
		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	}
	return sub, err
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}
