179	// ErrNotDue means a subscription was renewed or canceled since it was read as due, so the call changed nothing.
180	var ErrNotDue = errors.New("the subscription is not due")
181	
182	// RenewSubscription moves a subscription into its next period [start, end). It applies only while the subscription is still
183	// due: it must not be canceled, and its current period must still end at dueEnd. Otherwise another call already renewed or
184	// canceled it, and ErrNotDue is returned with nothing stored. When inv is set, that invoice is stored in the same step, so a
185	// period is invoiced at most once however many calls race.
186	func (s *Store) RenewSubscription(orgID, subID string, dueEnd, start, end time.Time, inv *Invoice, now time.Time) (Subscription, *Invoice, error) {
187		s.mu.Lock()
188		defer s.mu.Unlock()
189		old, ok := s.subs[subID]
190		if !ok || old.OrgID != orgID {
191			return Subscription{}, nil, ErrNotFound
192		}
193		if old.Status == Canceled || !old.CurrentPeriodEnd.Equal(dueEnd) {
194			return Subscription{}, nil, ErrNotDue
195		}
196		var stored *Invoice
197		if inv != nil {
198			if err := checkInvoice(*inv); err != nil {
199				return Subscription{}, nil, err
200			}
201			created, err := s.createInvoice(*inv, now)
202			if err != nil {
203				return Subscription{}, nil, err
204			}
205			stored = &created
206		}
207		sub := copySub(old)
208		sub.CurrentPeriodStart, sub.CurrentPeriodEnd = start, end
209		s.subs[subID] = sub
210		return copySub(sub), stored, nil
211	}
