305	// createInvoice stores a checked invoice. The caller holds s.mu.
306	func (s *Store) createInvoice(inv Invoice, now time.Time) (Invoice, error) {
307		org, ok := s.orgs[inv.OrgID]
308		if !ok {
309			return Invoice{}, ErrNotFound
310		}
311		c, ok := s.customers[inv.CustomerID]
312		if !ok {
313			return Invoice{}, ErrNotFound
314		}
315		if c.OrgID != inv.OrgID {
316			return Invoice{}, ErrCustomerOrgMismatch
317		}
318		inv.ID = s.newID("in")
319		inv.TaxRateBP = org.TaxRateBP
320		inv.Status = InvoiceOpen
321		inv.CreatedAt = now.UTC()
322		inv.PaidAt, inv.VoidedAt = nil, nil
