429		defer s.mu.Unlock()
430		inv, ok := s.invoices[p.InvoiceID]
431		if !ok || inv.OrgID != p.OrgID {
432			return Payment{}, ErrNotFound
433		}
434		if p.Status != PaymentSucceeded && p.Status != PaymentFailed {
435			return Payment{}, invalid("a payment succeeded or failed")
436		}
437		p.ID = s.newID("pay")
438		p.CreatedAt = now.UTC()
439		s.payments[p.ID] = p
440		return p, nil
441	}
442	
443	// Payments returns an organization's payments, oldest first, only those of one invoice when invoiceID is set.
444	func (s *Store) Payments(orgID, invoiceID string) []Payment {
445		s.mu.Lock()
446		defer s.mu.Unlock()
447		out := []Payment{}
448		for _, p := range s.payments {
449			if p.OrgID == orgID && (invoiceID == "" || p.InvoiceID == invoiceID) {
450				out = append(out, p)
451			}
452		}
453		sort.Slice(out, func(i, j int) bool {
454			if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
455				return out[i].CreatedAt.Before(out[j].CreatedAt)
456			}
457			return out[i].ID < out[j].ID
458		})
459		return out
460	}
