13	// CreatePlan adds a plan. UsageType defaults to Licensed; a new plan is active.
14	func (s *Store) CreatePlan(p Plan, now time.Time) (Plan, error) {
15		p.Name = strings.TrimSpace(p.Name)
16		if p.UsageType == "" {
17			p.UsageType = Licensed
18		}
19		p.Active = true
20		if err := checkPlan(p); err != nil {
21			return Plan{}, err
22		}
23		s.mu.Lock()
24		defer s.mu.Unlock()
25		if _, ok := s.orgs[p.OrgID]; !ok {
26			return Plan{}, ErrNotFound
27		}
28		p.ID = s.newID("plan")
29		p.CreatedAt = now.UTC()
30		s.plans[p.ID] = p
31		return p, nil
32	}
