34	func checkPlan(p Plan) error {
35		switch {
36		case p.Name == "":
37			return invalid("a plan needs a name")
38		case !p.Currency.Valid():
39			return invalid("unknown currency %q", p.Currency)
40		case p.UnitAmount < 0:
41			return invalid("a plan's price cannot be negative")
42		case p.Interval != Monthly && p.Interval != Yearly:
43			return invalid("a plan bills every month or every year")
44		case p.UsageType != Licensed && p.UsageType != Metered:
45			return invalid("a plan is licensed or metered")
46		case p.TrialDays < 0 || p.TrialDays > 365:
47			return invalid("a trial lasts 0 to 365 days")
48		}
49		return nil
50	}
