77	// UpdatePlan changes a plan with f. Its currency, price, interval and usage type cannot change once created: subscriptions
78	// depend on them.
79	func (s *Store) UpdatePlan(orgID, id string, f func(*Plan) error) (Plan, error) {
80		s.mu.Lock()
81		defer s.mu.Unlock()
82		old, ok := s.plans[id]
83		if !ok || old.OrgID != orgID {
84			return Plan{}, ErrNotFound
