91		p.Currency, p.UnitAmount, p.Interval, p.UsageType = old.Currency, old.UnitAmount, old.Interval, old.UsageType
92		p.Name = strings.TrimSpace(p.Name)
93		if err := checkPlan(p); err != nil {
94			return Plan{}, err
95		}
96		s.plans[id] = p
97		return p, nil
98	}
