109		}
110		s.mu.Lock()
111		defer s.mu.Unlock()
112		if _, ok := s.customers[sub.CustomerID]; !ok {
113			return Subscription{}, ErrNotFound
114		}
115		if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != sub.OrgID {
116			return Subscription{}, ErrNotFound
117		}
118		sub.ID = s.newID("sub")
119		sub.CreatedAt = now.UTC()
120		s.subs[sub.ID] = sub
