156	// UpdateSubscription changes a subscription with f, which may refuse with an error.
157	func (s *Store) UpdateSubscription(orgID, id string, f func(*Subscription) error) (Subscription, error) {
158		s.mu.Lock()
159		defer s.mu.Unlock()
160		old, ok := s.subs[id]
161		if !ok || old.OrgID != orgID {
162			return Subscription{}, ErrNotFound
163		}
164		sub := copySub(old)
165		if err := f(&sub); err != nil {
166			return Subscription{}, err
167		}
168		sub.ID, sub.OrgID, sub.CustomerID, sub.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.CreatedAt
169		if sub.Quantity <= 0 {
170			return Subscription{}, invalid("the quantity must be at least 1")
171		}
172		if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != orgID {
173			return Subscription{}, ErrNotFound
174		}
175		s.subs[id] = sub
176		return copySub(sub), nil
177	}
