213	// DueSubscriptions returns the subscriptions of every organization whose current period has ended by now and that are not
214	// canceled, the longest overdue first.
215	func (s *Store) DueSubscriptions(now time.Time) []Subscription {
216		s.mu.Lock()
217		defer s.mu.Unlock()
218		out := []Subscription{}
219		for _, sub := range s.subs {
220			if sub.Status != Canceled && !sub.CurrentPeriodEnd.After(now) {
221				out = append(out, copySub(sub))
222			}
223		}
224		sort.Slice(out, func(i, j int) bool {
225			if !out[i].CurrentPeriodEnd.Equal(out[j].CurrentPeriodEnd) {
226				return out[i].CurrentPeriodEnd.Before(out[j].CurrentPeriodEnd)
227			}
228			return out[i].ID < out[j].ID
229		})
230		return out
231	}
