233	func copySub(sub Subscription) Subscription {
234		if sub.TrialEnd != nil {
235			t := *sub.TrialEnd
236			sub.TrialEnd = &t
237		}
238		if sub.CanceledAt != nil {
239			t := *sub.CanceledAt
240			sub.CanceledAt = &t
241		}
242		return sub
243	}
