246	func (s *Store) AddUsage(orgID, subID string, quantity int64, at, now time.Time) (UsageRecord, error) {
247		if quantity <= 0 {
248			return UsageRecord{}, invalid("usage must be a positive quantity")
249		}
250		s.mu.Lock()
251		defer s.mu.Unlock()
252		sub, ok := s.subs[subID]
253		if !ok || sub.OrgID != orgID {
254			return UsageRecord{}, ErrNotFound
255		}
256		if p := s.plans[sub.PlanID]; p.UsageType != Metered {
257			return UsageRecord{}, invalid("the subscription's plan is not metered")
258		}
259		u := UsageRecord{ID: s.newID("use"), OrgID: orgID, SubscriptionID: subID, Quantity: quantity, At: at.UTC(), CreatedAt: now.UTC()}
