264	// UsageTotal adds up a subscription's usage at times in [from, to).
265	func (s *Store) UsageTotal(orgID, subID string, from, to time.Time) int64 {
266		s.mu.Lock()
267		defer s.mu.Unlock()
268		var n int64
269		for _, u := range s.usage {
270			if u.OrgID == orgID && u.SubscriptionID == subID && !u.At.Before(from) && u.At.Before(to) {
271				n += u.Quantity
272			}
273		}
274		return n
275	}
