289	// checkInvoice validates the parts of an invoice that do not depend on stored data.
290	func checkInvoice(inv Invoice) error {
291		if !inv.Currency.Valid() {
292			return invalid("unknown currency %q", inv.Currency)
293		}
294		if inv.DiscountPercent < 0 || inv.DiscountPercent > 100 {
295			return invalid("the discount is 0 to 100 percent")
296		}
297		for _, l := range inv.Lines {
298			if l.Quantity <= 0 {
