348	type InvoiceFilter struct {
349		CustomerID     string
350		SubscriptionID string
351		Status         InvoiceStatus
352	}
353	
354	// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
355	func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
356		s.mu.Lock()
357		all := make([]Invoice, 0, len(s.invoices))
358		for _, inv := range s.invoices {
359			all = append(all, inv)
360		}
361		s.mu.Unlock()
362		out := []Invoice{}
363		for _, inv := range all {
364			c := cloneInvoice(inv)
365			if c.OrgID != orgID {
366				continue
367			}
368			if (f.CustomerID != "" && c.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && c.SubscriptionID != f.SubscriptionID) || (f.Status != "" && c.Status != f.Status) {
369				continue
370			}
371			out = append(out, c)
372		}
373		sort.Slice(out, func(i, j int) bool {
374			if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
375				return out[i].CreatedAt.Before(out[j].CreatedAt)
376			}
377			return out[i].ID < out[j].ID
378		})
379		return out
380	}
381	
382	// UpdateInvoice changes an invoice with f, which may refuse with an error. Only its status, timestamps and lines change.
383	func (s *Store) UpdateInvoice(orgID, id string, f func(*Invoice) error) (Invoice, error) {
384		s.mu.Lock()
385		defer s.mu.Unlock()
386		old, ok := s.invoices[id]
387		if !ok || old.OrgID != orgID {
388			return Invoice{}, ErrNotFound
389		}
390		inv := copyInvoice(old)
391		if err := f(&inv); err != nil {
392			return Invoice{}, err
393		}
394		inv.ID, inv.OrgID, inv.CustomerID, inv.SubscriptionID, inv.Currency, inv.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.SubscriptionID, old.Currency, old.CreatedAt
395		s.invoices[id] = copyInvoice(inv)
396		return copyInvoice(inv), nil
397	}
398	
399	// copyInvoice is a deep copy, so callers cannot change stored lines.
400	func copyInvoice(inv Invoice) Invoice {
401		inv.Lines = append([]Line(nil), inv.Lines...)
402		for _, p := range []**time.Time{&inv.PeriodStart, &inv.PeriodEnd, &inv.PaidAt, &inv.VoidedAt} {
403			if *p != nil {
404				t := **p
405				*p = &t
406			}
407		}
408		return inv
409	}
410	
411	// cloneInvoice is a deep copy through JSON, which cannot miss a field added later.
412	func cloneInvoice(inv Invoice) Invoice {
413		b, err := json.Marshal(inv)
414		if err != nil {
415			return copyInvoice(inv)
416		}
417		var out Invoice
418		if err := json.Unmarshal(b, &out); err != nil {
419			return copyInvoice(inv)
420		}
421		return out
422	}
