1	// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
2	// renewing them when a billing period ends.
3	package subscriptions
4	
5	import (
6		"context"
7		"errors"
8		"fmt"
9		"time"
10	
11		"example.com/tally/internal/billing"
12		"example.com/tally/internal/clock"
13		"example.com/tally/internal/payments"
14		"example.com/tally/internal/store"
15	)
16	
17	// Errors.
18	var (
19		ErrPlanInactive = errors.New("the plan is not active")
20		ErrCanceled     = errors.New("the subscription is canceled")
21	)
22	
23	// Service runs subscriptions.
24	type Service struct {
25		Store     *store.Store
26		Payments  *payments.Service
27		Clock     clock.Clock
28		Publisher payments.Publisher // nil: no events
29	}
30	
31	// CreateInput is a new subscription.
32	type CreateInput struct {
33		CustomerID      string
34		PlanID          string
35		Quantity        int // 0 means 1
36		DiscountPercent int
37	}
38	
39	// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
40	// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
41	// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
42	func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
43		plan, ok := s.Store.Plan(orgID, in.PlanID)
44		if !ok {
45			return store.Subscription{}, store.ErrNotFound
46		}
47		if !plan.Active {
48			return store.Subscription{}, ErrPlanInactive
49		}
50		if in.Quantity == 0 {
51			in.Quantity = 1
52		}
53		now := s.Clock.Now()
54		sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
55			StartedAt: now, CurrentPeriodStart: now}
56		if plan.TrialDays > 0 {
57			end := now.AddDate(0, 0, plan.TrialDays)
58			sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
59		} else {
60			sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
61		}
62		sub, err := s.Store.CreateSubscription(sub, now)
63		if err != nil {
64			return store.Subscription{}, err
65		}
66		s.publish(ctx, orgID, "subscription.created", sub)
67		if sub.Status == store.Active && plan.UsageType == store.Licensed {
68			inv, err := s.Store.CreateInvoice(s.periodInvoice(sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd), now)
69			if err != nil {
70				return sub, err
71			}
72			paid, err := s.collect(ctx, inv)
73			if err != nil {
74				return sub, err
75			}
76			if !paid {
77				if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
78					return sub, err
79				}
80			}
81		}
82		return sub, nil
83	}
84	
85	// UpdateInput changes a subscription; nil fields stay as they are.
86	type UpdateInput struct {
87		PlanID   *string
88		Quantity *int
89	}
90	
91	// Update changes a subscription's plan or quantity. The change applies at once and is billed from the next period on.
92	func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
93		if in.PlanID != nil {
94			p, ok := s.Store.Plan(orgID, *in.PlanID)
95			if !ok {
96				return store.Subscription{}, store.ErrNotFound
97			}
98			if !p.Active {
99				return store.Subscription{}, ErrPlanInactive
100			}
101		}
102		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
103			if sub.Status == store.Canceled {
104				return ErrCanceled
105			}
106			if in.PlanID != nil {
107				sub.PlanID = *in.PlanID
108			}
109			if in.Quantity != nil {
110				sub.Quantity = *in.Quantity
111			}
112			return nil
113		})
114		if err != nil {
115			return store.Subscription{}, err
116		}
117		s.publish(ctx, orgID, "subscription.updated", sub)
118		return sub, nil
119	}
120	
121	// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
122	// subscription changes nothing.
123	func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
124		now := s.Clock.Now()
125		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
126			if sub.Status == store.Canceled {
127				return nil
128			}
129			if atPeriodEnd {
130				sub.CancelAtPeriodEnd = true
131				return nil
132			}
133			sub.Status, sub.CanceledAt = store.Canceled, &now
134			return nil
135		})
136		if err != nil {
137			return store.Subscription{}, err
138		}
139		if sub.Status == store.Canceled {
140			s.publish(ctx, orgID, "subscription.canceled", sub)
141		} else {
142			s.publish(ctx, orgID, "subscription.updated", sub)
143		}
144		return sub, nil
145	}
