147	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
148	// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
149	// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
150	// due. RenewDue keeps going when one subscription fails, and returns the errors after trying them all. An unavailable
151	// gateway still renews the subscription: its invoice stays open and its status is kept, and the error is returned. RenewDue
152	// returns how many subscriptions it renewed or canceled.
153	func (s *Service) RenewDue(ctx context.Context) (int, error) {
154		now := s.Clock.Now()
155		n := 0
156		var errs []error
157		for _, sub := range s.Store.DueSubscriptions(now) {
158			if err := ctx.Err(); err != nil {
159				errs = append(errs, err)
160				break
161			}
162			renewed, err := s.renew(ctx, sub, now)
163			if renewed {
164				n++
165			}
166			if err != nil {
167				errs = append(errs, fmt.Errorf("renew %s: %w", sub.ID, err))
168			}
169		}
170		return n, errors.Join(errs...)
171	}
172	
173	// renew moves a due subscription into its next period and bills it. The period moves before the charge, under the store's
174	// lock, so a subscription is renewed once per period even when calls overlap, and a failed charge is not billed again by a
175	// later call. It reports whether this call renewed or canceled the subscription. A subscription that another call already
176	// moved on is left alone without an error.
177	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) (bool, error) {
178		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
179		if !ok {
180			return false, store.ErrNotFound
181		}
182		dueEnd := sub.CurrentPeriodEnd
183		if sub.CancelAtPeriodEnd {
184			canceled, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
185				if x.Status == store.Canceled || !x.CurrentPeriodEnd.Equal(dueEnd) {
186					return store.ErrNotDue
187				}
188				x.Status, x.CanceledAt = store.Canceled, &dueEnd
189				return nil
190			})
191			if errors.Is(err, store.ErrNotDue) {
192				return false, nil
193			}
194			if err != nil {
195				return false, err
196			}
197			s.publish(ctx, canceled.OrgID, "subscription.canceled", canceled)
198			return true, nil
199		}
200		start := now
201		end := billing.AddInterval(start, plan.Interval)
202		var invoice *store.Invoice
203		switch {
204		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
205			inv := s.periodInvoice(sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
206			invoice = &inv
207		case plan.UsageType == store.Licensed:
208			inv := s.periodInvoice(sub, plan, start, end)
209			invoice = &inv
210		}
211		next, inv, err := s.Store.RenewSubscription(sub.OrgID, sub.ID, dueEnd, start, end, invoice, now)
212		if errors.Is(err, store.ErrNotDue) {
213			return false, nil
214		}
215		if err != nil {
216			return false, err
217		}
218		paid := true
219		if inv != nil {
220			if paid, err = s.collect(ctx, *inv); err != nil {
221				// The gateway failed: nothing was taken, the invoice stays open and the status is kept.
222				s.publish(ctx, next.OrgID, "subscription.updated", next)
223				return true, err
224			}
225		}
226		status := store.Active
227		if !paid {
228			status = store.PastDue
229		}
230		if _, err := s.setStatus(ctx, next, status); err != nil {
231			return true, err
232		}
233		return true, nil
234	}
235	
236	// periodInvoice builds, without storing it, the invoice of one period of a subscription.
237	func (s *Service) periodInvoice(sub store.Subscription, plan store.Plan, start, end time.Time) store.Invoice {
238		var lines []store.Line
239		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
240		switch plan.UsageType {
241		case store.Licensed:
242			if plan.UnitAmount > 0 {
243				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
244			}
245		case store.Metered:
246			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
247				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
248			}
249		}
250		ps, pe := start, end
251		return store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
252			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}
253	}
254	
255	// collect charges a stored invoice to the customer's default payment method. It reports false when the charge was declined.
256	// An invoice that needs no charge is marked paid; one whose customer has no payment method stays open and counts as paid
257	// here (it is paid by hand). An unavailable gateway returns an error wrapping payments.ErrUnavailable.
258	func (s *Service) collect(ctx context.Context, inv store.Invoice) (bool, error) {
259		s.publish(ctx, inv.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": inv.SubscriptionID})
260		_, _, err := s.Payments.Pay(ctx, inv.OrgID, inv.ID, "")
261		var decline *payments.DeclineError
262		switch {
263		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
264			return true, nil
265		case errors.As(err, &decline):
266			return false, nil
267		default:
268			return false, err
269		}
270	}
271	
272	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
273		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
274			x.Status = st
275			return nil
276		})
277		if err == nil {
278			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
279		}
280		return sub, err
281	}
282	
283	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
284		if s.Publisher != nil {
285			_ = s.Publisher.Publish(ctx, orgID, typ, data)
286		}
287	}
