func TestRenewSubscriptionOnlyWhileDue(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	p, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.USD, UnitAmount: 2000, Interval: Monthly}, t0)
	end := t0.AddDate(0, 1, 0)
	sub, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: c.ID, PlanID: p.ID, Quantity: 1, Status: Active,
		StartedAt: t0, CurrentPeriodStart: t0, CurrentPeriodEnd: end}, t0)
	if err != nil {
		t.Fatal(err)
	}
	next := end.AddDate(0, 1, 0)
	inv := Invoice{OrgID: a.ID, CustomerID: c.ID, SubscriptionID: sub.ID, Currency: money.USD, Lines: []Line{{Description: "Pro", Quantity: 1, UnitAmount: 2000}}, PeriodStart: &end, PeriodEnd: &next}
	got, stored, err := s.RenewSubscription(a.ID, sub.ID, end, end, next, &inv, end)
	if err != nil || stored == nil || stored.Status != InvoiceOpen || !got.CurrentPeriodStart.Equal(end) || !got.CurrentPeriodEnd.Equal(next) {
		t.Fatalf("RenewSubscription = %+v, %+v, %v", got, stored, err)
	}
	// A call that read the subscription before the renewal above must not renew or invoice the same period again.
	again := inv
	again.PeriodStart = &next
	if _, stored, err := s.RenewSubscription(a.ID, sub.ID, end, next, next.AddDate(0, 1, 0), &again, end); !errors.Is(err, ErrNotDue) || stored != nil {
		t.Fatalf("stale renewal: stored %+v, %v", stored, err)
	}
	if invs := s.ListInvoices(a.ID, InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("invoices = %+v, want one", invs)
	}
}

