// ErrNotDue means a subscription was renewed or canceled since it was read as due, so the call changed nothing.
var ErrNotDue = errors.New("the subscription is not due")

// RenewSubscription moves a subscription into its next period [start, end). It applies only while the subscription is still
// due: it must not be canceled, and its current period must still end at dueEnd. Otherwise another call already renewed or
// canceled it, and ErrNotDue is returned with nothing stored. When inv is set, that invoice is stored in the same step, so a
// period is invoiced at most once however many calls race.
func (s *Store) RenewSubscription(orgID, subID string, dueEnd, start, end time.Time, inv *Invoice, now time.Time) (Subscription, *Invoice, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.subs[subID]
	if !ok || old.OrgID != orgID {
		return Subscription{}, nil, ErrNotFound
	}
	if old.Status == Canceled || !old.CurrentPeriodEnd.Equal(dueEnd) {
		return Subscription{}, nil, ErrNotDue
	}
	var stored *Invoice
	if inv != nil {
		if err := checkInvoice(*inv); err != nil {
			return Subscription{}, nil, err
		}
		created, err := s.createInvoice(*inv, now)
		if err != nil {
			return Subscription{}, nil, err
		}
		stored = &created
	}

