func TestRenewalClaimHoldsWhenThePeriodReadsStale(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	p, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.USD, UnitAmount: 2000, Interval: Monthly}, t0)
	end := t0.AddDate(0, 1, 0)
	sub, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: c.ID, PlanID: p.ID, Quantity: 1, Status: Active,
		StartedAt: t0, CurrentPeriodStart: t0, CurrentPeriodEnd: end}, t0)
	if err != nil {
		t.Fatal(err)
	}
	next := end.AddDate(0, 1, 0)
	inv := Invoice{OrgID: a.ID, CustomerID: c.ID, SubscriptionID: sub.ID, Currency: money.USD, Lines: []Line{{Description: "Pro", Quantity: 1, UnitAmount: 2000}}, PeriodStart: &end, PeriodEnd: &next}
	if _, _, err := s.RenewSubscription(a.ID, sub.ID, end, end, next, &inv, end); err != nil {
		t.Fatal(err)
	}
	// A copy of the store whose subscription row still shows the first period, as a stale read would. Its renewal of the
	// second period must not invoice that period again, and the claim must come through an export and reload.
	st := s.Export()
	if len(st.RenewalClaims) != 1 || st.RenewalClaims[0].SubscriptionID != sub.ID {
		t.Fatalf("RenewalClaims = %+v, want one claim for %s", st.RenewalClaims, sub.ID)
	}
	for i := range st.Subscriptions {
		st.Subscriptions[i].CurrentPeriodStart, st.Subscriptions[i].CurrentPeriodEnd = t0, end
	}
	stale, err := FromState(st)
	if err != nil {
		t.Fatal(err)
	}
	again := inv
	if _, stored, err := stale.RenewSubscription(a.ID, sub.ID, end, end, next, &again, end); !errors.Is(err, ErrNotDue) || stored != nil {
		t.Fatalf("stale renewal of a claimed period: stored %+v, %v", stored, err)
	}
	if invs := stale.ListInvoices(a.ID, InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("invoices = %+v, want one", invs)
	}
	st.RenewalClaims = append(st.RenewalClaims, st.RenewalClaims[0])
	if _, err := FromState(st); !errors.Is(err, ErrInvalid) {
		t.Fatalf("a period invoiced twice was accepted: %v", err)
	}
}
