// Package store keeps Tally's data in memory. It is safe for concurrent use.
//
// Every object belongs to one organization. Methods that take an orgID only ever see that organization's objects; the few
// methods that find an object by ID alone (CustomerByID, InvoiceByID, EventByID) are for background jobs and the admin
// tool, which act on behalf of the system rather than a member.
package store

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"
)

// Errors. Callers check them with errors.Is; most are wrapped with a detail.
var (
	ErrNotFound      = errors.New("not found")
	ErrInvalid       = errors.New("invalid")
	ErrConflict      = errors.New("conflict")
	ErrEmailTaken    = fmt.Errorf("%w: email address already in use", ErrConflict)
	ErrAlreadyMember = fmt.Errorf("%w: already a member", ErrConflict)
	// ErrCustomerOrgMismatch is returned when an object names a customer of another organization.
	ErrCustomerOrgMismatch = errors.New("customer belongs to another organization")
)

// Store holds everything.
type Store struct {
	mu  sync.Mutex
	seq int

	orgs         map[string]Org
	users        map[string]User
	usersByEmail map[string]string // lower-case email -> user ID
	members      map[memberKey]Member
	apiKeys      map[string]APIKey
	keysByToken  map[string]string // token -> key ID
	invites      map[string]Invite

	customers        map[string]Customer
	customersByEmail map[string]string // lower-case email -> customer ID

	plans     map[string]Plan
	subs      map[string]Subscription
	usage     []UsageRecord
	invoices  map[string]Invoice
	renewals  map[renewalKey]string // (subscription, period start) -> renewal invoice ID
	payments  map[string]Payment
	endpoints map[string]WebhookEndpoint
	events    map[string]Event
	delivs    map[string]Delivery
}

type memberKey struct{ org, user string }

// renewalKey identifies the renewal invoice of one subscription period. start is the period start in Unix nanoseconds.
type renewalKey struct {
	sub   string
	start int64
}

// New returns an empty store.
func New() *Store {
	return &Store{
		orgs: map[string]Org{}, users: map[string]User{}, usersByEmail: map[string]string{}, members: map[memberKey]Member{},
		apiKeys: map[string]APIKey{}, keysByToken: map[string]string{}, invites: map[string]Invite{},
		customers: map[string]Customer{}, customersByEmail: map[string]string{},
		plans: map[string]Plan{}, subs: map[string]Subscription{}, invoices: map[string]Invoice{}, renewals: map[renewalKey]string{},
		payments: map[string]Payment{},
		endpoints: map[string]WebhookEndpoint{}, events: map[string]Event{}, delivs: map[string]Delivery{},
	}
}

// newID returns the next ID with the prefix, for example "cus_000042". The caller holds the lock.
func (s *Store) newID(prefix string) string {
	s.seq++
	return fmt.Sprintf("%s_%06d", prefix, s.seq)
}

// NewToken returns prefix followed by 32 random hex characters.
func NewToken(prefix string) string {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		panic(err) // crypto/rand does not fail on supported platforms
	}
	return prefix + hex.EncodeToString(b)
}

func normEmail(email string) string { return strings.ToLower(strings.TrimSpace(email)) }

func validEmail(email string) bool {
	at := strings.Index(email, "@")
	return at > 0 && at < len(email)-1 && !strings.ContainsAny(email, " \t\r\n,;<>")
}

func invalid(format string, args ...any) error {
	return fmt.Errorf("%w: %s", ErrInvalid, fmt.Sprintf(format, args...))
}

// ---- organizations

// CreateOrg adds an organization.
func (s *Store) CreateOrg(name string, plan OrgPlan, timeZone string, taxRateBP int, now time.Time) (Org, error) {
	o := Org{Name: strings.TrimSpace(name), Plan: plan, TimeZone: timeZone, TaxRateBP: taxRateBP, CreatedAt: now.UTC()}
	if err := checkOrg(o); err != nil {
		return Org{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	o.ID = s.newID("org")
	s.orgs[o.ID] = o
	return o, nil
}

func checkOrg(o Org) error {
	if o.Name == "" {
		return invalid("an organization needs a name")
	}
	if !o.Plan.Valid() {
		return invalid("unknown plan %q", o.Plan)
	}
	if _, err := time.LoadLocation(o.TimeZone); err != nil || o.TimeZone == "" {
		return invalid("unknown time zone %q", o.TimeZone)
	}
	if o.TaxRateBP < 0 || o.TaxRateBP > 10000 {
		return invalid("the tax rate is 0 to 10000 basis points")
	}
	return nil
}

// Org returns an organization.
func (s *Store) Org(id string) (Org, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[id]
	return o, ok
}

// UpdateOrg changes an organization with f, which may refuse with an error.
func (s *Store) UpdateOrg(id string, f func(*Org) error) (Org, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[id]
	if !ok {
		return Org{}, ErrNotFound
	}
	if err := f(&o); err != nil {
		return Org{}, err
	}
	o.ID = id
	if err := checkOrg(o); err != nil {
		return Org{}, err
	}
	s.orgs[id] = o
	return o, nil
}

// ---- users and members

// CreateUser adds a user. Email addresses are unique, ignoring case.
func (s *Store) CreateUser(email, name string, now time.Time) (User, error) {
	email, name = strings.TrimSpace(email), strings.TrimSpace(name)
	if !validEmail(email) {
		return User{}, invalid("a user needs a valid email address")
	}
	if name == "" {
		return User{}, invalid("a user needs a name")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.usersByEmail[normEmail(email)]; ok {
		return User{}, ErrEmailTaken
	}
	u := User{ID: s.newID("usr"), Email: email, Name: name, CreatedAt: now.UTC()}
	s.users[u.ID] = u
	s.usersByEmail[normEmail(email)] = u.ID
	return u, nil
}

// User returns a user.
func (s *Store) User(id string) (User, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	u, ok := s.users[id]
	return u, ok
}

// UserByEmail finds a user by email address, ignoring case.
func (s *Store) UserByEmail(email string) (User, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	id, ok := s.usersByEmail[normEmail(email)]
	if !ok {
		return User{}, false
	}
	return s.users[id], true
}

// AddMember makes a user a member of an organization.
func (s *Store) AddMember(orgID, userID string, role Role, now time.Time) (Member, error) {
	if !role.Valid() {
		return Member{}, invalid("unknown role %q", role)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.addMember(orgID, userID, role, now)
}

func (s *Store) addMember(orgID, userID string, role Role, now time.Time) (Member, error) {
	if _, ok := s.orgs[orgID]; !ok {
		return Member{}, ErrNotFound
	}
	if _, ok := s.users[userID]; !ok {
		return Member{}, ErrNotFound
	}
	k := memberKey{orgID, userID}
	if _, ok := s.members[k]; ok {
		return Member{}, ErrAlreadyMember
	}
	m := Member{OrgID: orgID, UserID: userID, Role: role, CreatedAt: now.UTC()}
	s.members[k] = m
	return m, nil
}

// Member returns a user's membership of an organization.
func (s *Store) Member(orgID, userID string) (Member, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	m, ok := s.members[memberKey{orgID, userID}]
	return m, ok
}

// Members returns an organization's members, oldest first.
func (s *Store) Members(orgID string) []Member {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Member{}
	for _, m := range s.members {
		if m.OrgID == orgID {
			out = append(out, m)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].UserID < out[j].UserID
	})
	return out
}

// SetMemberRole changes a member's role.
func (s *Store) SetMemberRole(orgID, userID string, role Role) (Member, error) {
	if !role.Valid() {
		return Member{}, invalid("unknown role %q", role)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return Member{}, ErrNotFound
	}
	m.Role = role
	s.members[k] = m
	return m, nil
}

// RemoveMember removes a user from an organization. Their API keys for it stop working, as they are no longer a member.
func (s *Store) RemoveMember(orgID, userID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	if _, ok := s.members[k]; !ok {
		return ErrNotFound
	}
	delete(s.members, k)
	return nil
}

// ---- API keys

// CreateAPIKey gives a member a new API key.
func (s *Store) CreateAPIKey(orgID, userID, name string, now time.Time) (APIKey, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.createAPIKey(orgID, userID, name, now)
}

func (s *Store) createAPIKey(orgID, userID, name string, now time.Time) (APIKey, error) {
	if _, ok := s.members[memberKey{orgID, userID}]; !ok {
		return APIKey{}, ErrNotFound
	}
	name = strings.TrimSpace(name)
	if name == "" {
		name = "API key"
	}
	k := APIKey{ID: s.newID("key"), OrgID: orgID, UserID: userID, Name: name, Token: NewToken("tly_"), CreatedAt: now.UTC()}
	s.apiKeys[k.ID] = k
	s.keysByToken[k.Token] = k.ID
	return k, nil
}

// APIKeyByToken finds the key a request presented. Revoked keys are returned too; the caller checks RevokedAt.
func (s *Store) APIKeyByToken(token string) (APIKey, bool) {
	if token == "" {
		return APIKey{}, false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	id, ok := s.keysByToken[token]
	if !ok {
		return APIKey{}, false
	}
	return s.apiKeys[id], true
}

// APIKey returns one of an organization's keys.
func (s *Store) APIKey(orgID, id string) (APIKey, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	k, ok := s.apiKeys[id]
	if !ok || k.OrgID != orgID {
		return APIKey{}, false
	}
	return k, true
}

// APIKeys returns an organization's keys, oldest first.
func (s *Store) APIKeys(orgID string) []APIKey {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []APIKey{}
	for _, k := range s.apiKeys {
		if k.OrgID == orgID {
			out = append(out, k)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// RevokeAPIKey stops a key from working.
func (s *Store) RevokeAPIKey(orgID, id string, now time.Time) (APIKey, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	k, ok := s.apiKeys[id]
	if !ok || k.OrgID != orgID {
		return APIKey{}, ErrNotFound
	}
	if k.RevokedAt == nil {
		t := now.UTC()
		k.RevokedAt = &t
		s.apiKeys[id] = k
	}
	return k, nil
}

// TouchAPIKey records that a key was used.
func (s *Store) TouchAPIKey(id string, now time.Time) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if k, ok := s.apiKeys[id]; ok {
		t := now.UTC()
		k.LastUsedAt = &t
		s.apiKeys[id] = k
	}
}

// ---- invites

// CreateInvite invites an email address to join an organization with a role.
func (s *Store) CreateInvite(orgID, email string, role Role, invitedBy string, now time.Time) (Invite, error) {
	email = strings.TrimSpace(email)
	if !validEmail(email) {
		return Invite{}, invalid("an invite needs a valid email address")
	}
	if !role.Valid() || role == RoleOwner {
		return Invite{}, invalid("an invite's role is admin, billing, member or viewer")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[orgID]; !ok {
		return Invite{}, ErrNotFound
	}
	if uid, ok := s.usersByEmail[normEmail(email)]; ok {
		if _, member := s.members[memberKey{orgID, uid}]; member {
			return Invite{}, ErrAlreadyMember
		}
	}
	inv := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, Token: NewToken("invite_"), InvitedBy: invitedBy, CreatedAt: now.UTC()}
	s.invites[inv.ID] = inv
	return inv, nil
}

// Invite returns one of an organization's invites.
func (s *Store) Invite(orgID, id string) (Invite, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invites[id]
	if !ok || inv.OrgID != orgID {
		return Invite{}, false
	}
	return inv, true
}

// Invites returns an organization's invites that were neither accepted nor revoked, oldest first.
func (s *Store) Invites(orgID string) []Invite {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Invite{}
	for _, inv := range s.invites {
		if inv.OrgID == orgID && inv.AcceptedAt == nil && inv.RevokedAt == nil {
			out = append(out, inv)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// RevokeInvite withdraws an invite.
func (s *Store) RevokeInvite(orgID, id string, now time.Time) (Invite, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invites[id]
	if !ok || inv.OrgID != orgID {
		return Invite{}, ErrNotFound
	}
	if inv.RevokedAt == nil {
		t := now.UTC()
		inv.RevokedAt = &t
		s.invites[id] = inv
	}
	return inv, nil
}

// AcceptInvite accepts the invite with this token: it finds or creates the user for the invited address (named name),
// makes them a member with the invite's role and gives them a first API key.
func (s *Store) AcceptInvite(token, name string, now time.Time) (User, Member, APIKey, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	var inv Invite
	found := false
	for _, i := range s.invites {
		if i.Token == token && token != "" {
			inv, found = i, true
			break
		}
	}
	if !found || inv.RevokedAt != nil {
		return User{}, Member{}, APIKey{}, ErrNotFound
	}
	var u User
	if id, ok := s.usersByEmail[normEmail(inv.Email)]; ok {
		u = s.users[id]
	} else {
		name = strings.TrimSpace(name)
		if name == "" {
			return User{}, Member{}, APIKey{}, invalid("a new user needs a name")
		}
		u = User{ID: s.newID("usr"), Email: inv.Email, Name: name, CreatedAt: now.UTC()}
		s.users[u.ID] = u
		s.usersByEmail[normEmail(u.Email)] = u.ID
	}
	m, err := s.addMember(inv.OrgID, u.ID, inv.Role, now)
	if err != nil {
		return User{}, Member{}, APIKey{}, err
	}
	k, err := s.createAPIKey(inv.OrgID, u.ID, "Default", now)
	if err != nil {
		return User{}, Member{}, APIKey{}, err
	}
	t := now.UTC()
	inv.AcceptedAt = &t
	s.invites[inv.ID] = inv
	return u, m, k, nil
}
package store

import (
	"fmt"
	"sort"
	"time"
)

// State is everything a store holds, for snapshots (package snapshot). Slices are sorted by ID.
type State struct {
	Seq              int               `json:"seq"`
	Orgs             []Org             `json:"orgs"`
	Users            []User            `json:"users"`
	Members          []Member          `json:"members"`
	APIKeys          []APIKey          `json:"api_keys"`
	Invites          []Invite          `json:"invites"`
	Customers        []Customer        `json:"customers"`
	Plans            []Plan            `json:"plans"`
	Subscriptions    []Subscription    `json:"subscriptions"`
	Usage            []UsageRecord     `json:"usage"`
	Invoices         []Invoice         `json:"invoices"`
	RenewalClaims    []RenewalClaim    `json:"renewal_claims,omitempty"`
	Payments         []Payment         `json:"payments"`
	WebhookEndpoints []WebhookEndpoint `json:"webhook_endpoints"`
	Events           []Event           `json:"events"`
	Deliveries       []Delivery        `json:"deliveries"`
}

// Export returns a copy of everything in the store.
func (s *Store) Export() State {
	s.mu.Lock()
	defer s.mu.Unlock()
	st := State{Seq: s.seq}
	for _, o := range s.orgs {
		st.Orgs = append(st.Orgs, o)
	}
	for _, u := range s.users {
		st.Users = append(st.Users, u)
	}
	for _, m := range s.members {
		st.Members = append(st.Members, m)
	}
	for _, k := range s.apiKeys {
		st.APIKeys = append(st.APIKeys, k)
	}
	for _, i := range s.invites {
		st.Invites = append(st.Invites, i)
	}
	for _, c := range s.customers {
		st.Customers = append(st.Customers, copyCustomer(c))
	}
	for _, p := range s.plans {
		st.Plans = append(st.Plans, p)
	}
	for _, sub := range s.subs {
		st.Subscriptions = append(st.Subscriptions, copySub(sub))
	}
	st.Usage = append(st.Usage, s.usage...)
	for _, inv := range s.invoices {
		st.Invoices = append(st.Invoices, copyInvoice(inv))
	}
	for k, id := range s.renewals {
		st.RenewalClaims = append(st.RenewalClaims, RenewalClaim{SubscriptionID: k.sub, PeriodStart: time.Unix(0, k.start).UTC(), InvoiceID: id})
	}
	for _, p := range s.payments {
		st.Payments = append(st.Payments, p)
	}
	for _, ep := range s.endpoints {
		st.WebhookEndpoints = append(st.WebhookEndpoints, copyEndpoint(ep))
	}
	for _, e := range s.events {
		st.Events = append(st.Events, e)
	}
	for _, d := range s.delivs {
		st.Deliveries = append(st.Deliveries, copyDelivery(d))
	}
	sort.Slice(st.Orgs, func(i, j int) bool { return st.Orgs[i].ID < st.Orgs[j].ID })
	sort.Slice(st.Users, func(i, j int) bool { return st.Users[i].ID < st.Users[j].ID })
	sort.Slice(st.Members, func(i, j int) bool {
		if st.Members[i].OrgID != st.Members[j].OrgID {
			return st.Members[i].OrgID < st.Members[j].OrgID
		}
		return st.Members[i].UserID < st.Members[j].UserID
	})
	sort.Slice(st.APIKeys, func(i, j int) bool { return st.APIKeys[i].ID < st.APIKeys[j].ID })
	sort.Slice(st.Invites, func(i, j int) bool { return st.Invites[i].ID < st.Invites[j].ID })
	sort.Slice(st.Customers, func(i, j int) bool { return st.Customers[i].ID < st.Customers[j].ID })
	sort.Slice(st.Plans, func(i, j int) bool { return st.Plans[i].ID < st.Plans[j].ID })
	sort.Slice(st.Subscriptions, func(i, j int) bool { return st.Subscriptions[i].ID < st.Subscriptions[j].ID })
	sort.Slice(st.Usage, func(i, j int) bool { return st.Usage[i].ID < st.Usage[j].ID })
	sort.Slice(st.Invoices, func(i, j int) bool { return st.Invoices[i].ID < st.Invoices[j].ID })
	sort.Slice(st.RenewalClaims, func(i, j int) bool {
		a, b := st.RenewalClaims[i], st.RenewalClaims[j]
		if a.SubscriptionID != b.SubscriptionID {
			return a.SubscriptionID < b.SubscriptionID
		}
		return a.PeriodStart.Before(b.PeriodStart)
	})
	sort.Slice(st.Payments, func(i, j int) bool { return st.Payments[i].ID < st.Payments[j].ID })
	sort.Slice(st.WebhookEndpoints, func(i, j int) bool { return st.WebhookEndpoints[i].ID < st.WebhookEndpoints[j].ID })
	sort.Slice(st.Events, func(i, j int) bool { return st.Events[i].ID < st.Events[j].ID })
	sort.Slice(st.Deliveries, func(i, j int) bool { return st.Deliveries[i].ID < st.Deliveries[j].ID })
	return st
}

// FromState builds a store holding st.
func FromState(st State) (*Store, error) {
	s := New()
	s.seq = st.Seq
	dup := func(kind, id string, seen map[string]bool) error {
		if id == "" || seen[id] {
			return fmt.Errorf("%w: %s %q is missing or repeated", ErrInvalid, kind, id)
		}
		seen[id] = true
		return nil
	}
	seen := map[string]bool{}
	for _, o := range st.Orgs {
		if err := dup("organization", o.ID, seen); err != nil {
			return nil, err
		}
		s.orgs[o.ID] = o
	}
	for _, u := range st.Users {
		if err := dup("user", u.ID, seen); err != nil {
			return nil, err
		}
		s.users[u.ID] = u
		s.usersByEmail[normEmail(u.Email)] = u.ID
	}
	for _, m := range st.Members {
		if _, ok := s.orgs[m.OrgID]; !ok {
			return nil, fmt.Errorf("%w: member of unknown organization %q", ErrInvalid, m.OrgID)
		}
		if _, ok := s.users[m.UserID]; !ok {
			return nil, fmt.Errorf("%w: member is unknown user %q", ErrInvalid, m.UserID)
		}
		s.members[memberKey{m.OrgID, m.UserID}] = m
	}
	for _, k := range st.APIKeys {
		if err := dup("API key", k.ID, seen); err != nil {
			return nil, err
		}
		s.apiKeys[k.ID] = k
		if k.Token != "" {
			s.keysByToken[k.Token] = k.ID
		}
	}
	for _, i := range st.Invites {
		if err := dup("invite", i.ID, seen); err != nil {
			return nil, err
		}
		s.invites[i.ID] = i
	}
	for _, c := range st.Customers {
		if err := dup("customer", c.ID, seen); err != nil {
			return nil, err
		}
		s.customers[c.ID] = copyCustomer(c)
		s.customersByEmail[normEmail(c.Email)] = c.ID
	}
	for _, p := range st.Plans {
		if err := dup("plan", p.ID, seen); err != nil {
			return nil, err
		}
		s.plans[p.ID] = p
	}
	for _, sub := range st.Subscriptions {
		if err := dup("subscription", sub.ID, seen); err != nil {
			return nil, err
		}
		s.subs[sub.ID] = copySub(sub)
	}
	s.usage = append(s.usage, st.Usage...)
	for _, inv := range st.Invoices {
		if err := dup("invoice", inv.ID, seen); err != nil {
			return nil, err
		}
		s.invoices[inv.ID] = copyInvoice(inv)
	}
	for _, c := range st.RenewalClaims {
		_, subOK := s.subs[c.SubscriptionID]
		_, invOK := s.invoices[c.InvoiceID]
		if !subOK || !invOK {
			return nil, fmt.Errorf("%w: renewal claim names an unknown subscription or invoice", ErrInvalid)
		}
		k := renewalKey{sub: c.SubscriptionID, start: c.PeriodStart.UnixNano()}
		if _, dup := s.renewals[k]; dup {
			return nil, fmt.Errorf("%w: subscription %q period %s is invoiced twice", ErrInvalid, c.SubscriptionID, c.PeriodStart)
		}
		s.renewals[k] = c.InvoiceID
	}
	for _, p := range st.Payments {
		if err := dup("payment", p.ID, seen); err != nil {
			return nil, err
		}
		s.payments[p.ID] = p
	}
	for _, ep := range st.WebhookEndpoints {
		if err := dup("webhook endpoint", ep.ID, seen); err != nil {
			return nil, err
		}
		s.endpoints[ep.ID] = copyEndpoint(ep)
	}
	for _, e := range st.Events {
		if err := dup("event", e.ID, seen); err != nil {
			return nil, err
		}
		s.events[e.ID] = e
	}
	for _, d := range st.Deliveries {
		if err := dup("delivery", d.ID, seen); err != nil {
			return nil, err
		}
		s.delivs[d.ID] = copyDelivery(d)
	}
	return s, nil
}

// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
// renewing them when a billing period ends.
package subscriptions

import (
	"context"
	"errors"
	"fmt"
	"time"

	"example.com/tally/internal/billing"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// Errors.
var (
	ErrPlanInactive = errors.New("the plan is not active")
	ErrCanceled     = errors.New("the subscription is canceled")
)

// Service runs subscriptions.
type Service struct {
	Store     *store.Store
	Payments  *payments.Service
	Clock     clock.Clock
	Publisher payments.Publisher // nil: no events
}

// CreateInput is a new subscription.
type CreateInput struct {
	CustomerID      string
	PlanID          string
	Quantity        int // 0 means 1
	DiscountPercent int
}

// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
	plan, ok := s.Store.Plan(orgID, in.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if !plan.Active {
		return store.Subscription{}, ErrPlanInactive
	}
	if in.Quantity == 0 {
		in.Quantity = 1
	}
	now := s.Clock.Now()
	sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
		StartedAt: now, CurrentPeriodStart: now}
	if plan.TrialDays > 0 {
		end := now.AddDate(0, 0, plan.TrialDays)
		sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
	} else {
		sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
	}
	sub, err := s.Store.CreateSubscription(sub, now)
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.created", sub)
	if sub.Status == store.Active && plan.UsageType == store.Licensed {
		inv, err := s.Store.CreateInvoice(s.periodInvoice(sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd), now)
		if err != nil {
			return sub, err
		}
		paid, err := s.collect(ctx, inv)
		if err != nil {
			return sub, err
		}
		if !paid {
			if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
				return sub, err
			}
		}
	}
	return sub, nil
}

// UpdateInput changes a subscription; nil fields stay as they are.
type UpdateInput struct {
	PlanID   *string
	Quantity *int
}

// Update changes a subscription's plan or quantity. The change applies at once and is billed from the next period on.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return ErrCanceled
		}
		if in.PlanID != nil {
			sub.PlanID = *in.PlanID
		}
		if in.Quantity != nil {
			sub.Quantity = *in.Quantity
		}
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	return sub, nil
}

// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
// subscription changes nothing.
func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
	now := s.Clock.Now()
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return nil
		}
		if atPeriodEnd {
			sub.CancelAtPeriodEnd = true
			return nil
		}
		sub.Status, sub.CanceledAt = store.Canceled, &now
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	if sub.Status == store.Canceled {
		s.publish(ctx, orgID, "subscription.canceled", sub)
	} else {
		s.publish(ctx, orgID, "subscription.updated", sub)
	}
	return sub, nil
}

// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
// due. RenewDue keeps going when one subscription fails, and returns the errors after trying them all. An unavailable
// gateway still renews the subscription: its invoice stays open and its status is kept, and the error is returned. RenewDue
// returns how many subscriptions it renewed or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	var errs []error
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			errs = append(errs, err)
			break
		}
		renewed, err := s.renew(ctx, sub, now)
		if renewed {
			n++
		}
		if err != nil {
			errs = append(errs, fmt.Errorf("renew %s: %w", sub.ID, err))
		}
	}
	return n, errors.Join(errs...)
}

// renew moves a due subscription into its next period and bills it. The period moves before the charge, under the store's
// lock, so a subscription is renewed once per period even when calls overlap, and a failed charge is not billed again by a
// later call. It reports whether this call renewed or canceled the subscription. A subscription that another call already
// moved on is left alone without an error.
func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) (bool, error) {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return false, store.ErrNotFound
	}
	dueEnd := sub.CurrentPeriodEnd
	if sub.CancelAtPeriodEnd {
		canceled, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			if x.Status == store.Canceled || !x.CurrentPeriodEnd.Equal(dueEnd) {
				return store.ErrNotDue
			}
			x.Status, x.CanceledAt = store.Canceled, &dueEnd
			return nil
		})
		if errors.Is(err, store.ErrNotDue) {
			return false, nil
		}
		if err != nil {
			return false, err
		}
		s.publish(ctx, canceled.OrgID, "subscription.canceled", canceled)
		return true, nil
	}
	start := now
	end := billing.AddInterval(start, plan.Interval)
	var invoice *store.Invoice
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		inv := s.periodInvoice(sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		invoice = &inv
	case plan.UsageType == store.Licensed:
		inv := s.periodInvoice(sub, plan, start, end)
		invoice = &inv
	}
	next, inv, err := s.Store.RenewSubscription(sub.OrgID, sub.ID, dueEnd, start, end, invoice, now)
	if errors.Is(err, store.ErrNotDue) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	paid := true
	if inv != nil {
		if paid, err = s.collect(ctx, *inv); err != nil {
			// The gateway failed: nothing was taken, the invoice stays open and the status is kept.
			s.publish(ctx, next.OrgID, "subscription.updated", next)
			return true, err
		}
	}
	status := store.Active
	if !paid {
		status = store.PastDue
	}
	if _, err := s.setStatus(ctx, next, status); err != nil {
		return true, err
	}
	return true, nil
}

// periodInvoice builds, without storing it, the invoice of one period of a subscription.
func (s *Service) periodInvoice(sub store.Subscription, plan store.Plan, start, end time.Time) store.Invoice {
	var lines []store.Line
	period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
	switch plan.UsageType {
	case store.Licensed:
		if plan.UnitAmount > 0 {
			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
		}
	case store.Metered:
		if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
			lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
		}
	}
	ps, pe := start, end
	return store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}
}

// collect charges a stored invoice to the customer's default payment method. It reports false when the charge was declined.
// An invoice that needs no charge is marked paid; one whose customer has no payment method stays open and counts as paid
// here (it is paid by hand). An unavailable gateway returns an error wrapping payments.ErrUnavailable.
func (s *Service) collect(ctx context.Context, inv store.Invoice) (bool, error) {
	s.publish(ctx, inv.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": inv.SubscriptionID})
	_, _, err := s.Payments.Pay(ctx, inv.OrgID, inv.ID, "")
	var decline *payments.DeclineError
	switch {
	case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
		return true, nil
	case errors.As(err, &decline):
		return false, nil
	default:
		return false, err
	}
}

func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
	sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.Status = st
		return nil
	})
	if err == nil {
		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	}
	return sub, err
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}
// Package snapshot saves the store to a JSON file and loads it back, so the server keeps its data across restarts. The
// file carries a version; files written by older versions of Tally are migrated when they are loaded.
package snapshot

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// Version is the version Save writes.
const Version = 2

// ErrUnsupportedVersion is returned for a file of a version Load cannot read.
var ErrUnsupportedVersion = errors.New("unsupported snapshot version")

type fileV2 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

// Save writes everything in st to path.
func Save(st *store.Store, path string, now time.Time) error {
	b, err := json.MarshalIndent(fileV2{Version: Version, SavedAt: now.UTC(), State: st.Export()}, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, append(b, '\n'), 0o600)
}

// Load reads a snapshot written by Save, or by an older version of Tally, and returns a store holding it.
func Load(path string) (*store.Store, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return nil, fmt.Errorf("snapshot %s: %w", path, err)
	}
	var st store.State
	switch head.Version {
	case 1:
		if st, err = migrateV1(b); err != nil {
			return nil, fmt.Errorf("snapshot %s: version 1: %w", path, err)
		}
	case 2:
		var f fileV2
		if err := json.Unmarshal(b, &f); err != nil {
			return nil, fmt.Errorf("snapshot %s: %w", path, err)
		}
		st = f.State
	default:
		return nil, fmt.Errorf("snapshot %s: %w %d", path, ErrUnsupportedVersion, head.Version)
	}
	return store.FromState(st)
}

// Version 1 (Tally 0.x) kept the state at the top level. Organizations had no plan or time zone, customers had a
// full_name, and plans had a price in US cents (price_cents) and were all licensed.
type fileV1 struct {
	Seq           int                  `json:"seq"`
	Orgs          []orgV1              `json:"orgs"`
	Users         []store.User         `json:"users"`
	Members       []store.Member       `json:"members"`
	APIKeys       []store.APIKey       `json:"api_keys"`
	Customers     []customerV1         `json:"customers"`
	Plans         []planV1             `json:"plans"`
	Subscriptions []store.Subscription `json:"subscriptions"`
	Invoices      []store.Invoice      `json:"invoices"`
	Payments      []store.Payment      `json:"payments"`
}

type orgV1 struct {
	ID        string    `json:"id"`
	Name      string    `json:"name"`
	TaxRateBP int       `json:"tax_rate_bp"`
	CreatedAt time.Time `json:"created_at"`
}

type customerV1 struct {
	ID        string    `json:"id"`
	OrgID     string    `json:"org_id"`
	FullName  string    `json:"full_name"`
	Email     string    `json:"email"`
	CreatedAt time.Time `json:"created_at"`
}

type planV1 struct {
	ID         string         `json:"id"`
	OrgID      string         `json:"org_id"`
	Name       string         `json:"name"`
	PriceCents int64          `json:"price_cents"`
	Interval   store.Interval `json:"interval"`
	TrialDays  int            `json:"trial_days"`
	CreatedAt  time.Time      `json:"created_at"`
}

func migrateV1(b []byte) (store.State, error) {
	var f fileV1
	if err := json.Unmarshal(b, &f); err != nil {
		return store.State{}, err
	}
	st := store.State{Seq: f.Seq, Users: f.Users, Members: f.Members, APIKeys: f.APIKeys, Subscriptions: f.Subscriptions, Invoices: f.Invoices, Payments: f.Payments}
	for _, o := range f.Orgs {
		st.Orgs = append(st.Orgs, store.Org{ID: o.ID, Name: o.Name, Plan: store.OrgFree, TimeZone: "UTC", TaxRateBP: o.TaxRateBP, CreatedAt: o.CreatedAt})
	}
	for _, c := range f.Customers {
		st.Customers = append(st.Customers, store.Customer{ID: c.ID, OrgID: c.OrgID, Name: c.FullName, Email: c.Email, CreatedAt: c.CreatedAt})
	}
	for _, p := range f.Plans {
		st.Plans = append(st.Plans, store.Plan{ID: p.ID, OrgID: p.OrgID, Name: p.Name, Currency: money.USD, UnitAmount: p.PriceCents, Interval: p.Interval,
			UsageType: store.Licensed, TrialDays: p.TrialDays, Active: true, CreatedAt: p.CreatedAt})
	}
	return st, nil
}

// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
// renewing them when a billing period ends.
package subscriptions

import (
	"context"
	"errors"
	"fmt"
	"time"

	"example.com/tally/internal/billing"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// Errors.
var (
	ErrPlanInactive = errors.New("the plan is not active")
	ErrCanceled     = errors.New("the subscription is canceled")
)

// Service runs subscriptions.
type Service struct {
	Store     *store.Store
	Payments  *payments.Service
	Clock     clock.Clock
	Publisher payments.Publisher // nil: no events
}

// CreateInput is a new subscription.
type CreateInput struct {
	CustomerID      string
	PlanID          string
	Quantity        int // 0 means 1
	DiscountPercent int
}

// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
	plan, ok := s.Store.Plan(orgID, in.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if !plan.Active {
		return store.Subscription{}, ErrPlanInactive
	}
	if in.Quantity == 0 {
		in.Quantity = 1
	}
	now := s.Clock.Now()
	sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
		StartedAt: now, CurrentPeriodStart: now}
	if plan.TrialDays > 0 {
		end := now.AddDate(0, 0, plan.TrialDays)
		sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
	} else {
		sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
	}
	sub, err := s.Store.CreateSubscription(sub, now)
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.created", sub)
	if sub.Status == store.Active && plan.UsageType == store.Licensed {
		inv, err := s.Store.CreateInvoice(s.periodInvoice(sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd), now)
		if err != nil {
			return sub, err
		}
		paid, err := s.collect(ctx, inv)
		if err != nil {
			return sub, err
		}
		if !paid {
			if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
				return sub, err
			}
		}
	}
	return sub, nil
}

// UpdateInput changes a subscription; nil fields stay as they are.
type UpdateInput struct {
	PlanID   *string
	Quantity *int
}

// Update changes a subscription's plan or quantity. The change applies at once and is billed from the next period on.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return ErrCanceled
		}
		if in.PlanID != nil {
			sub.PlanID = *in.PlanID
		}
		if in.Quantity != nil {
			sub.Quantity = *in.Quantity
		}
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	return sub, nil
}

// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
// subscription changes nothing.
func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
	now := s.Clock.Now()
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return nil
		}
		if atPeriodEnd {
			sub.CancelAtPeriodEnd = true
			return nil
		}
		sub.Status, sub.CanceledAt = store.Canceled, &now
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	if sub.Status == store.Canceled {
		s.publish(ctx, orgID, "subscription.canceled", sub)
	} else {
		s.publish(ctx, orgID, "subscription.updated", sub)
	}
	return sub, nil
}

// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
// due. RenewDue keeps going when one subscription fails, and returns the errors after trying them all. An unavailable
// gateway still renews the subscription: its invoice stays open and its status is kept, and the error is returned. RenewDue
// returns how many subscriptions it renewed or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	var errs []error
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			errs = append(errs, err)
			break
		}
		renewed, err := s.renew(ctx, sub, now)
		if renewed {
			n++
		}
		if err != nil {
			errs = append(errs, fmt.Errorf("renew %s: %w", sub.ID, err))
		}
	}
	return n, errors.Join(errs...)
}

// renew moves a due subscription into its next period and bills it. The period moves before the charge, under the store's
// lock, so a subscription is renewed once per period even when calls overlap, and a failed charge is not billed again by a
// later call. It reports whether this call renewed or canceled the subscription. A subscription that another call already
// moved on is left alone without an error.
func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) (bool, error) {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return false, store.ErrNotFound
	}
	dueEnd := sub.CurrentPeriodEnd
	if sub.CancelAtPeriodEnd {
		canceled, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			if x.Status == store.Canceled || !x.CurrentPeriodEnd.Equal(dueEnd) {
				return store.ErrNotDue
			}
			x.Status, x.CanceledAt = store.Canceled, &dueEnd
			return nil
		})
		if errors.Is(err, store.ErrNotDue) {
			return false, nil
		}
		if err != nil {
			return false, err
		}
		s.publish(ctx, canceled.OrgID, "subscription.canceled", canceled)
		return true, nil
	}
	start := now
	end := billing.AddInterval(start, plan.Interval)
	var invoice *store.Invoice
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		inv := s.periodInvoice(sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		invoice = &inv
	case plan.UsageType == store.Licensed:
		inv := s.periodInvoice(sub, plan, start, end)
		invoice = &inv
	}
	next, inv, err := s.Store.RenewSubscription(sub.OrgID, sub.ID, dueEnd, start, end, invoice, now)
	if errors.Is(err, store.ErrNotDue) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	paid := true
	if inv != nil {
		if paid, err = s.collect(ctx, *inv); err != nil {
			// The gateway failed: nothing was taken, the invoice stays open and the status is kept.
			s.publish(ctx, next.OrgID, "subscription.updated", next)
			return true, err
		}
	}
	status := store.Active
	if !paid {
		status = store.PastDue
	}
	if _, err := s.setStatus(ctx, next, status); err != nil {
		return true, err
	}
	return true, nil
}

// periodInvoice builds, without storing it, the invoice of one period of a subscription.
func (s *Service) periodInvoice(sub store.Subscription, plan store.Plan, start, end time.Time) store.Invoice {
	var lines []store.Line
	period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
	switch plan.UsageType {
	case store.Licensed:
		if plan.UnitAmount > 0 {
			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
		}
	case store.Metered:
		if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
			lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
		}
	}
	ps, pe := start, end
	return store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}
}

// collect charges a stored invoice to the customer's default payment method. It reports false when the charge was declined.
// An invoice that needs no charge is marked paid; one whose customer has no payment method stays open and counts as paid
// here (it is paid by hand). An unavailable gateway returns an error wrapping payments.ErrUnavailable.
func (s *Service) collect(ctx context.Context, inv store.Invoice) (bool, error) {
	s.publish(ctx, inv.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": inv.SubscriptionID})
	_, _, err := s.Payments.Pay(ctx, inv.OrgID, inv.ID, "")
	var decline *payments.DeclineError
	switch {
	case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
		return true, nil
	case errors.As(err, &decline):
		return false, nil
	default:
		return false, err
	}
}

func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
	sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.Status = st
		return nil
	})
	if err == nil {
		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	}
	return sub, err
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}
// Package snapshot saves the store to a JSON file and loads it back, so the server keeps its data across restarts. The
// file carries a version; files written by older versions of Tally are migrated when they are loaded.
package snapshot

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// Version is the version Save writes.
const Version = 2

// ErrUnsupportedVersion is returned for a file of a version Load cannot read.
var ErrUnsupportedVersion = errors.New("unsupported snapshot version")

type fileV2 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

// Save writes everything in st to path.
func Save(st *store.Store, path string, now time.Time) error {
	b, err := json.MarshalIndent(fileV2{Version: Version, SavedAt: now.UTC(), State: st.Export()}, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, append(b, '\n'), 0o600)
}

// Load reads a snapshot written by Save, or by an older version of Tally, and returns a store holding it.
func Load(path string) (*store.Store, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return nil, fmt.Errorf("snapshot %s: %w", path, err)
	}
	var st store.State
	switch head.Version {
	case 1:
		if st, err = migrateV1(b); err != nil {
			return nil, fmt.Errorf("snapshot %s: version 1: %w", path, err)
		}
	case 2:
		var f fileV2
		if err := json.Unmarshal(b, &f); err != nil {
			return nil, fmt.Errorf("snapshot %s: %w", path, err)
		}
		st = f.State
	default:
		return nil, fmt.Errorf("snapshot %s: %w %d", path, ErrUnsupportedVersion, head.Version)
	}
	return store.FromState(st)
}

// Version 1 (Tally 0.x) kept the state at the top level. Organizations had no plan or time zone, customers had a
// full_name, and plans had a price in US cents (price_cents) and were all licensed.
type fileV1 struct {
	Seq           int                  `json:"seq"`
	Orgs          []orgV1              `json:"orgs"`
	Users         []store.User         `json:"users"`
	Members       []store.Member       `json:"members"`
	APIKeys       []store.APIKey       `json:"api_keys"`
	Customers     []customerV1         `json:"customers"`
	Plans         []planV1             `json:"plans"`
	Subscriptions []store.Subscription `json:"subscriptions"`
	Invoices      []store.Invoice      `json:"invoices"`
	Payments      []store.Payment      `json:"payments"`
}

type orgV1 struct {
	ID        string    `json:"id"`
	Name      string    `json:"name"`
	TaxRateBP int       `json:"tax_rate_bp"`
	CreatedAt time.Time `json:"created_at"`
}

type customerV1 struct {
	ID        string    `json:"id"`
	OrgID     string    `json:"org_id"`
	FullName  string    `json:"full_name"`
	Email     string    `json:"email"`
	CreatedAt time.Time `json:"created_at"`
}

type planV1 struct {
	ID         string         `json:"id"`
	OrgID      string         `json:"org_id"`
	Name       string         `json:"name"`
	PriceCents int64          `json:"price_cents"`
	Interval   store.Interval `json:"interval"`
	TrialDays  int            `json:"trial_days"`
	CreatedAt  time.Time      `json:"created_at"`
}

func migrateV1(b []byte) (store.State, error) {
	var f fileV1
	if err := json.Unmarshal(b, &f); err != nil {
		return store.State{}, err
	}
	st := store.State{Seq: f.Seq, Users: f.Users, Members: f.Members, APIKeys: f.APIKeys, Subscriptions: f.Subscriptions, Invoices: f.Invoices, Payments: f.Payments}
	for _, o := range f.Orgs {
		st.Orgs = append(st.Orgs, store.Org{ID: o.ID, Name: o.Name, Plan: store.OrgFree, TimeZone: "UTC", TaxRateBP: o.TaxRateBP, CreatedAt: o.CreatedAt})
	}
	for _, c := range f.Customers {
		st.Customers = append(st.Customers, store.Customer{ID: c.ID, OrgID: c.OrgID, Name: c.FullName, Email: c.Email, CreatedAt: c.CreatedAt})
	}
	for _, p := range f.Plans {
		st.Plans = append(st.Plans, store.Plan{ID: p.ID, OrgID: p.OrgID, Name: p.Name, Currency: money.USD, UnitAmount: p.PriceCents, Interval: p.Interval,
			UsageType: store.Licensed, TrialDays: p.TrialDays, Active: true, CreatedAt: p.CreatedAt})
	}
	return st, nil
}

