// renewableSub starts a licensed subscription, charged to pm_card_visa when it starts, and sets the customer's payment method
// to pm for the renewal. The clock is set to the end of the first period, when the subscription is due.
func renewableSub(t *testing.T, e *apitest.Env, email, pm string) store.Subscription {
	t.Helper()
	c := e.CreateCustomer(e.Acme, "Jane", email)
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = pm; return nil })
	e.Clock.Set(sub.CurrentPeriodEnd)
	return sub
}

func TestOverlappingRenewalsInvoiceOnce(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := renewableSub(t, e, "jane@example.com", "pm_card_visa")
	const runs = 8
	var wg sync.WaitGroup
	start := make(chan struct{})
	renewed := make([]int, runs)
	for i := 0; i < runs; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			n, err := e.Subs.RenewDue(ctx)
			if err != nil {
				t.Error(err)
			}
			renewed[i] = n
		}()
	}
	close(start)
	wg.Wait()
	total := 0
	for _, n := range renewed {
		total += n
	}
	if total != 1 {
		t.Fatalf("renewed %d times by %d overlapping runs, want once: %v", total, runs, renewed)
	}
	if n, err := e.Subs.RenewDue(ctx); n != 0 || err != nil {
		t.Fatalf("a later run renewed again: %d, %v", n, err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 2 || invs[1].Status != store.InvoicePaid {
		t.Fatalf("invoices = %+v, want the first period and one paid renewal", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 {
		t.Fatalf("charges = %d, want 2 (the first period and one renewal)", len(cs))
	}
}

func TestGatewayDownKeepsInvoiceOpenAndMovesPeriod(t *testing.T) {
	e := apitest.New(t)
