	first := sub.CurrentPeriodEnd
	if n, err := e.Subs.RenewDue(ctx); n != 1 || !errors.Is(err, payments.ErrUnavailable) {
		t.Fatalf("RenewDue = %d, %v; want one renewal and ErrUnavailable", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.Active || !got.CurrentPeriodStart.Equal(first) || !got.CurrentPeriodEnd.Equal(first.AddDate(0, 1, 0)) {
		t.Fatalf("after the outage = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[1].Status != store.InvoiceOpen {
		t.Fatalf("invoices = %+v, want the renewal open", invs)
	}
	calls := len(e.Gateway.Calls())
	if n, err := e.Subs.RenewDue(ctx); n != 0 || err != nil {
		t.Fatalf("the next run renewed again: %d, %v", n, err)
	}
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, sub.CustomerID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	if n, err := e.Subs.RenewDue(ctx); n != 0 || err != nil {
		t.Fatalf("a run after the gateway came back renewed again: %d, %v", n, err)
	}
	if got := len(e.Gateway.Calls()); got != calls {
		t.Fatalf("the gateway was called again for the open invoice: %d calls, want %d", got, calls)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 2 || invs[1].Status != store.InvoiceOpen {
		t.Fatalf("invoices = %+v, want the renewal still open", invs)
	}
}

