// invoiceOrg checks that the invoice's organization and customer exist and belong together, and returns the organization. The
// caller holds s.mu.
func (s *Store) invoiceOrg(inv Invoice) (Org, error) {
	org, ok := s.orgs[inv.OrgID]
	if !ok {
		return Org{}, ErrNotFound
	}
	c, ok := s.customers[inv.CustomerID]
	if !ok {
		return Org{}, ErrNotFound
	}
	if c.OrgID != inv.OrgID {
		return Org{}, ErrCustomerOrgMismatch
	}
	return org, nil
}

// periodInvoiced reports whether a renewal invoice of the subscription already starts its period at start. It also finds
