// Package ledger shares renewal claims between the instances of Tally that use one directory. A claim is a file created with
// O_EXCL, which the file system makes atomic: when instances claim the same period, exactly one creates the file. The
// instances must see the same directory. That covers instances on one host, or on a shared file system with atomic exclusive
// create. Instances on separate hosts need a database shared by all of them.
package ledger

import (
	"errors"
	"io/fs"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"time"
)

// Dir keeps renewal claims as files in a directory. It implements store.RenewalLedger.
type Dir struct {
	path string
}

// Open returns the ledger in dir, creating the directory when it is missing.
func Open(dir string) (*Dir, error) {
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return nil, err
	}
	return &Dir{path: dir}, nil
}

// Claim creates the claim for the subscription's period starting at periodStart. It reports false when the claim already
// exists, whichever instance created it.
func (d *Dir) Claim(subID string, periodStart time.Time) (bool, error) {
	name := url.PathEscape(subID) + "@" + strconv.FormatInt(periodStart.UnixNano(), 10)
	f, err := os.OpenFile(filepath.Join(d.path, name), os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if errors.Is(err, fs.ErrExist) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	return true, f.Close()
}

