	if l.claims[k] {
		return false, nil
	}
	l.claims[k] = true
	return true, nil
}

// renewableStore returns a store with one active subscription that ends at t0+1 month, and that end.
func renewableStore(t *testing.T) (*Store, Subscription, time.Time) {
	t.Helper()
	s := New()
	a := newOrg(t, s, "A")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	p, _ := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.USD, UnitAmount: 2000, Interval: Monthly}, t0)
	end := t0.AddDate(0, 1, 0)
	sub, err := s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: c.ID, PlanID: p.ID, Quantity: 1, Status: Active,
		StartedAt: t0, CurrentPeriodStart: t0, CurrentPeriodEnd: end}, t0)
	if err != nil {
		t.Fatal(err)
	}
	return s, sub, end
}

// renewalInvoice is the invoice of the period that starts at start for sub.
func renewalInvoice(sub Subscription, start time.Time) *Invoice {
	end := start.AddDate(0, 1, 0)
	return &Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: money.USD,
		Lines: []Line{{Description: "Pro", Quantity: 1, UnitAmount: 2000}}, PeriodStart: &start, PeriodEnd: &end}
}

func TestRenewalClaimIsSharedThroughTheLedger(t *testing.T) {
	s, sub, end := renewableStore(t)
	shared := &memLedger{}
	s.SetRenewalLedger(shared)
	// Two instances, each loaded from the same snapshot before any renewal, as two server processes are.
	st := s.Export()
	a, err := FromState(st)
	if err != nil {
		t.Fatal(err)
	}
	b, err := FromState(st)
	if err != nil {
		t.Fatal(err)
	}
	a.SetRenewalLedger(shared)
	b.SetRenewalLedger(shared)
	next := end.AddDate(0, 1, 0)
	if _, stored, err := a.RenewSubscription(sub.OrgID, sub.ID, end, end, next, renewalInvoice(sub, end), end); err != nil || stored == nil {
		t.Fatalf("first instance: stored %+v, %v", stored, err)
	}
	if _, stored, err := b.RenewSubscription(sub.OrgID, sub.ID, end, end, next, renewalInvoice(sub, end), end); !errors.Is(err, ErrNotDue) || stored != nil {
		t.Fatalf("second instance: stored %+v, %v; want ErrNotDue and nothing stored", stored, err)
	}
