		t.Fatalf("second instance invoiced the period: %+v", invs)
	}
	if got, _ := b.Subscription(sub.OrgID, sub.ID); !got.CurrentPeriodEnd.Equal(end) {
		t.Fatalf("second instance moved the period: %+v", got)
	}
}

func TestRenewalLedgerErrorStoresNothing(t *testing.T) {
	s, sub, end := renewableStore(t)
	s.SetRenewalLedger(&memLedger{err: errors.New("disk full")})
