	if _, stored, err := s.RenewSubscription(sub.OrgID, sub.ID, end, end, next, renewalInvoice(sub, end), end); err == nil || stored != nil {
		t.Fatalf("stored %+v, %v; want the ledger error and nothing stored", stored, err)
	}
	if got, _ := s.Subscription(sub.OrgID, sub.ID); !got.CurrentPeriodEnd.Equal(end) {
		t.Fatalf("the period moved without a claim: %+v", got)
	}
	if invs := s.ListInvoices(sub.OrgID, InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 0 {
		t.Fatalf("invoices = %+v, want none", invs)
	}
}

func TestRenewalSkipsPeriodsAlreadyInvoiced(t *testing.T) {
	s, sub, end := renewableStore(t)
	// An invoice for the period stored before renewals were claimed has no claim row.
	if _, err := s.CreateInvoice(*renewalInvoice(sub, end), end); err != nil {
		t.Fatal(err)
	}
	next := end.AddDate(0, 1, 0)
	if _, stored, err := s.RenewSubscription(sub.OrgID, sub.ID, end, end, next, renewalInvoice(sub, end), end); !errors.Is(err, ErrNotDue) || stored != nil {
		t.Fatalf("renewal of an invoiced period: stored %+v, %v", stored, err)
	}
	if invs := s.ListInvoices(sub.OrgID, InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("invoices = %+v, want the one that was there", invs)
	}
}
