201		end := billing.AddInterval(start, plan.Interval)
202		var invoice *store.Invoice
203		switch {
204		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
205			inv := s.periodInvoice(sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
206			invoice = &inv
207		case plan.UsageType == store.Licensed:
208			inv := s.periodInvoice(sub, plan, start, end)
209			invoice = &inv
210		}
211		next, inv, err := s.Store.RenewSubscription(sub.OrgID, sub.ID, dueEnd, start, end, invoice, now)
212		if errors.Is(err, store.ErrNotDue) {
213			return false, nil
214		}
215		if err != nil {
216			return false, err
217		}
218		paid := true
219		if inv != nil {
220			if paid, err = s.collect(ctx, *inv); err != nil {
221				// The gateway failed: nothing was taken, the invoice stays open and the status is kept.
222				s.publish(ctx, next.OrgID, "subscription.updated", next)
223				return true, err
224			}
225		}
226		status := store.Active
227		if !paid {
228			status = store.PastDue
229		}
230		if _, err := s.setStatus(ctx, next, status); err != nil {
231			return true, err
232		}
233		return true, nil
234	}
