236	// periodInvoice builds, without storing it, the invoice of one period of a subscription.
237	func (s *Service) periodInvoice(sub store.Subscription, plan store.Plan, start, end time.Time) store.Invoice {
238		var lines []store.Line
239		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
240		switch plan.UsageType {
241		case store.Licensed:
242			if plan.UnitAmount > 0 {
243				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
244			}
245		case store.Metered:
246			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
247				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
248			}
249		}
250		ps, pe := start, end
251		return store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
252			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}
253	}
