206	// RenewSubscription moves a subscription into its next period [start, end). It applies only while the subscription is still
207	// due: it must not be canceled, and its current period must still end at dueEnd. Otherwise another call already renewed or
208	// canceled it, and ErrNotDue is returned with nothing stored. When inv is set, that invoice is stored in the same step, and
209	// the (subscription, inv.PeriodStart) pair is claimed with it, in this store and in the shared ledger when there is one. A pair
210	// that is already claimed, or already has an invoice, also returns ErrNotDue, so a period is invoiced at most once however many
211	// calls race, however the subscription was read back, and however many instances run. A ledger error returns with nothing
212	// stored.
213	func (s *Store) RenewSubscription(orgID, subID string, dueEnd, start, end time.Time, inv *Invoice, now time.Time) (Subscription, *Invoice, error) {
214		s.mu.Lock()
215		defer s.mu.Unlock()
216		old, ok := s.subs[subID]
217		if !ok || old.OrgID != orgID {
218			return Subscription{}, nil, ErrNotFound
219		}
220		if old.Status == Canceled || !old.CurrentPeriodEnd.Equal(dueEnd) {
221			return Subscription{}, nil, ErrNotDue
222		}
223		var stored *Invoice
224		if inv != nil {
225			if err := checkInvoice(*inv); err != nil {
226				return Subscription{}, nil, err
227			}
228			if inv.PeriodStart == nil {
229				return Subscription{}, nil, invalid("a renewal invoice needs its period start")
230			}
231			k := renewalKey{sub: subID, start: inv.PeriodStart.UnixNano()}
232			if _, claimed := s.renewals[k]; claimed || s.periodInvoiced(subID, *inv.PeriodStart) {
233				return Subscription{}, nil, ErrNotDue
234			}
235			// Check the owners before claiming: a claim with no invoice behind it would leave the period unbilled for good.
236			if _, err := s.invoiceOrg(*inv); err != nil {
237				return Subscription{}, nil, err
238			}
239			if s.ledger != nil {
240				ok, err := s.ledger.Claim(subID, *inv.PeriodStart)
241				if err != nil {
242					return Subscription{}, nil, fmt.Errorf("claim renewal: %w", err)
243				}
244				if !ok {
245					return Subscription{}, nil, ErrNotDue
246				}
247			}
248			created, err := s.createInvoice(*inv, now)
249			if err != nil {
250				return Subscription{}, nil, err
251			}
252			s.renewals[k] = created.ID
253			stored = &created
254		}
255		sub := copySub(old)
256		sub.CurrentPeriodStart, sub.CurrentPeriodEnd = start, end
257		s.subs[subID] = sub
258		return copySub(sub), stored, nil
259	}
