261	// DueSubscriptions returns the subscriptions of every organization whose current period has ended by now and that are not
262	// canceled, the longest overdue first.
263	func (s *Store) DueSubscriptions(now time.Time) []Subscription {
264		s.mu.Lock()
265		defer s.mu.Unlock()
266		out := []Subscription{}
267		for _, sub := range s.subs {
268			if sub.Status != Canceled && !sub.CurrentPeriodEnd.After(now) {
269				out = append(out, copySub(sub))
270			}
271		}
272		sort.Slice(out, func(i, j int) bool {
273			if !out[i].CurrentPeriodEnd.Equal(out[j].CurrentPeriodEnd) {
274				return out[i].CurrentPeriodEnd.Before(out[j].CurrentPeriodEnd)
275			}
276			return out[i].ID < out[j].ID
277		})
278		return out
279	}
