func TestRenewalIsNotInvoicedAgainFromAStaleCopy(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := renewableSub(t, e, "jane@example.com", "pm_card_visa")
	periodStart, periodEnd := sub.CurrentPeriodStart, sub.CurrentPeriodEnd
	if n, err := e.Subs.RenewDue(ctx); n != 1 || err != nil {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	// A second service over a store restored from the first one's state, with the subscription row still on the first period.
	st := e.Store.Export()
	for i := range st.Subscriptions {
		if st.Subscriptions[i].ID == sub.ID {
			st.Subscriptions[i].CurrentPeriodStart, st.Subscriptions[i].CurrentPeriodEnd = periodStart, periodEnd
		}
	}
	copied, err := store.FromState(st)
	if err != nil {
		t.Fatal(err)
	}
	other := &subscriptions.Service{Store: copied, Payments: &payments.Service{Store: copied, Gateway: e.Gateway, Clock: e.Clock}, Clock: e.Clock}
	if n, err := other.RenewDue(ctx); n != 0 || err != nil {
		t.Fatalf("the stale copy renewed: %d, %v", n, err)
	}
	if invs := copied.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 2 {
		t.Fatalf("invoices = %+v, want the first period and one renewal", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 {
		t.Fatalf("charges = %d, want 2", len(cs))
	}
}

// instance returns a service over its own store, loaded from the snapshot st the way a server process loads its own. The
// instances share the gateway and the renewal ledger l.
func instance(t *testing.T, e *apitest.Env, st store.State, l store.RenewalLedger) *subscriptions.Service {
	t.Helper()
	s, err := store.FromState(st)
	if err != nil {
		t.Fatal(err)
	}
	s.SetRenewalLedger(l)
	return &subscriptions.Service{Store: s, Payments: &payments.Service{Store: s, Gateway: e.Gateway, Clock: e.Clock}, Clock: e.Clock}
}

func TestInstancesSharingALedgerInvoiceOnce(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := renewableSub(t, e, "jane@example.com", "pm_card_visa")
	l, err := ledger.Open(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	// Both instances start from the same snapshot, taken before the renewal, and run RenewDue at the same time.
	snapshot := e.Store.Export()
	instances := []*subscriptions.Service{instance(t, e, snapshot, l), instance(t, e, snapshot, l)}
	renewed := make([]int, len(instances))
	errs := make([]error, len(instances))
	var wg sync.WaitGroup
	for i, s := range instances {
		wg.Add(1)
		go func() {
			defer wg.Done()
			renewed[i], errs[i] = s.RenewDue(ctx)
		}()
	}
	wg.Wait()
	if renewed[0]+renewed[1] != 1 || errs[0] != nil || errs[1] != nil {
		t.Fatalf("RenewDue = %v, %v; want one renewal across the two instances", renewed, errs)
	}
	renewals := 0
	for _, s := range instances {
		for _, inv := range s.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}) {
			if inv.PeriodStart != nil && inv.PeriodStart.Equal(sub.CurrentPeriodEnd) {
				renewals++
			}
		}
	}
	if renewals != 1 {
		t.Fatalf("renewal invoices across the instances = %d, want 1", renewals)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 {
		t.Fatalf("charges = %d, want 2 (the first period and one renewal)", len(cs))
