func TestInstancesAtDifferentTimesInvoiceOnce(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := renewableSub(t, e, "jane@example.com", "pm_card_visa")
	l, err := ledger.Open(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	snapshot := e.Store.Export()
	before := len(e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}))
	// The instances' clocks disagree, as real servers' do: each renews at its own time after the period ended, so each would
	// start the new period at a different time. They must still agree on which renewal is due.
	clocks := []*clock.Fake{clock.NewFake(sub.CurrentPeriodEnd.Add(time.Minute)), clock.NewFake(sub.CurrentPeriodEnd.Add(time.Hour))}
	instances := []*subscriptions.Service{instance(t, e, snapshot, l, clocks[0]), instance(t, e, snapshot, l, clocks[1])}
	renewed := make([]int, len(instances))
	errs := make([]error, len(instances))
	var wg sync.WaitGroup
	for i, s := range instances {
		wg.Add(1)
		go func() {
			defer wg.Done()
			renewed[i], errs[i] = s.RenewDue(ctx)
		}()
	}
	wg.Wait()
	if renewed[0]+renewed[1] != 1 || errs[0] != nil || errs[1] != nil {
		t.Fatalf("RenewDue = %v, %v; want one renewal across the two instances", renewed, errs)
	}
	newInvoices := 0
	for _, s := range instances {
		newInvoices += len(s.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})) - before
	}
	if newInvoices != 1 {
		t.Fatalf("renewal invoices across the instances = %d, want 1", newInvoices)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 {
		t.Fatalf("charges = %d, want 2 (the first period and one renewal)", len(cs))
	}
}

