256	// An invoice that needs no charge is marked paid; one whose customer has no payment method stays open and counts as paid
257	// here (it is paid by hand). An unavailable gateway returns an error wrapping payments.ErrUnavailable.
258	func (s *Service) collect(ctx context.Context, inv store.Invoice) (bool, error) {
259		s.publish(ctx, inv.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": inv.SubscriptionID})
260		_, _, err := s.Payments.Pay(ctx, inv.OrgID, inv.ID, "")
261		var decline *payments.DeclineError
262		switch {
263		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
264			return true, nil
265		case errors.As(err, &decline):
266			return false, nil
267		default:
268			return false, err
269		}
270	}
