272	// setStatus sets a subscription's status, except that a subscription canceled meanwhile stays canceled.
273	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
274		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
275			if x.Status != store.Canceled {
276				x.Status = st
277			}
278			return nil
279		})
280		if err == nil {
281			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
282		}
283		return sub, err
284	}
